#!/usr/bin/env python3
"""UCI proxy. When it is White to move (the opponent's reply via engine.play),
return a deliberately bad legal move. When it is Black to move (evaluate()),
forward to the real engine so scores stay meaningful."""
import sys, os, subprocess, threading, chess, chess.engine

REAL = os.path.join(os.path.dirname(os.path.abspath(__file__)), "stockfish_real")

def parse_position(line):
    parts = line.split()
    if "startpos" in parts:
        b = chess.Board()
        if "moves" in parts:
            for m in parts[parts.index("moves")+1:]:
                b.push_uci(m)
        return b
    if "fen" in parts:
        i = parts.index("fen")
        fen_parts = []
        for p in parts[i+1:]:
            if p == "moves":
                break
            fen_parts.append(p)
        b = chess.Board(" ".join(fen_parts))
        if "moves" in parts:
            for m in parts[parts.index("moves")+1:]:
                b.push_uci(m)
        return b
    return chess.Board()

def weak_move(board):
    """Pick the legal move with the worst score for White, searched shallowly."""
    e = chess.engine.SimpleEngine.popen_uci(REAL)
    try:
        e.configure({"Threads": 2, "Hash": 128})
        legal = list(board.legal_moves)
        worst, worst_score = None, 10**9
        for m in legal:
            board.push(m)
            info = e.analyse(board, chess.engine.Limit(depth=5))
            sc = info["score"].white().score(mate_score=10000)
            board.pop()
            if sc is not None and sc < worst_score:
                worst_score, worst = sc, m
        return worst if worst else legal[0]
    finally:
        e.quit()

def main():
    proc = subprocess.Popen([REAL], stdin=subprocess.PIPE, stdout=subprocess.PIPE,
                            stderr=subprocess.DEVNULL, text=True, bufsize=1)
    board = chess.Board()
    out_lock = threading.Lock()

    def forward_output():
        for line in proc.stdout:
            with out_lock:
                sys.stdout.write(line)
                sys.stdout.flush()
    threading.Thread(target=forward_output, daemon=True).start()

    for line in sys.stdin:
        line = line.rstrip("\n")
        if line.startswith("position"):
            board = parse_position(line)
            proc.stdin.write(line + "\n"); proc.stdin.flush()
        elif line.startswith("go"):
            if board.turn == chess.WHITE:
                mv = weak_move(board)
                with out_lock:
                    sys.stdout.write("bestmove %s\n" % mv.uci())
                    sys.stdout.flush()
            else:
                proc.stdin.write(line + "\n"); proc.stdin.flush()
        elif line.strip() == "quit":
            proc.stdin.write(line + "\n"); proc.stdin.flush()
            break
        else:
            proc.stdin.write(line + "\n"); proc.stdin.flush()
    proc.terminate()

if __name__ == "__main__":
    main()
